-- FIUL · CUENTA DE PRUEBA de Juanba: copia del plan y las mediciones #8-#12 de Nicolás para probar la app como cliente.
-- Se borra después con 99_borrar_prueba.sql. No hace falta editar nada: correr tal cual.
do $do$
declare
  v_email text := 'juanba+prueba@coach4energy.com';
  v_id bigint;
begin
  if position('@' in v_email) = 0 then raise exception 'Falta reemplazar EMAIL_DE_NICOLAS por el email real'; end if;
  insert into public.clientes (nombre, email, fecha_alta, objetivo, fase_actual, servicio)
  values ('Juanba (prueba)', v_email, '2026-10-02', 'Recomposición corporal: 105 kg sin perder músculo (largo plazo 100 kg)', 'Déficit oct–dic 2026', 'Piloto')
  returning id into v_id;
  insert into public.planes (cliente_id, nombre, kcal_objetivo, proteina_objetivo_g, carbohidratos_objetivo_g, grasas_objetivo_g, tipos_dia, bloques, vigente_desde, vigente_hasta)
  values (v_id, 'Plan hiperproteico por bloques', 2400, 200, 230, 70, $j$[{"id": "lm", "nombre": "Lunes y miércoles", "dias": [1, 3], "comidas": [{"hora": "07:00", "titulo": "Desayuno + creatina", "detalle": "Jugo de naranja con 5 g de creatina, revuelto, tostadas, café o mate.", "p": 2, "h": 2}, {"hora": "12:30", "titulo": "Almuerzo", "detalle": "Proteína magra, medio plato de verdura, hidrato.", "p": 2, "h": 2}, {"hora": "16:00", "titulo": "Merienda", "detalle": "Yogur APIS Life o FuXion, y fruta.", "p": 1, "h": 2}, {"hora": "19:30", "titulo": "Cena", "detalle": "Proteína magra, verduras, hidrato.", "p": 2, "h": 2}]}, {"id": "mj", "nombre": "Martes y jueves (entreno)", "dias": [2, 4], "comidas": [{"hora": "07:00", "titulo": "Pre-entreno + creatina", "detalle": "Jugo de naranja con 5 g de creatina, café.", "p": 0, "h": 1}, {"hora": "10:00", "titulo": "Post-entreno", "detalle": "Revuelto, tostadas con Finlandia Light.", "p": 2, "h": 1}, {"hora": "13:00", "titulo": "Almuerzo", "detalle": "Proteína magra, medio plato de verdura, hidrato.", "p": 2, "h": 2}, {"hora": "16:00", "titulo": "Merienda", "detalle": "Yogur APIS Life o FuXion, y fruta.", "p": 1, "h": 2}, {"hora": "19:30", "titulo": "Cena", "detalle": "Proteína magra, verduras, hidrato.", "p": 2, "h": 2}]}, {"id": "vie", "nombre": "Viernes (tenis 9–10 h)", "dias": [5], "comidas": [{"hora": "07:30", "titulo": "Desayuno + creatina", "detalle": "Jugo de naranja con 5 g de creatina, 2 tostadas, revuelto 1 huevo + 4 claras. Liviano: entrás a la cancha 90 minutos después.", "p": 1, "h": 2}, {"hora": "09:00", "titulo": "Tenis", "detalle": "Agua durante el partido. Si hace calor, sumá sales de rehidratación.", "p": 0, "h": 0}, {"hora": "10:15", "titulo": "Post-tenis", "detalle": "FuXion BioPro+ Sport con agua y 1 fruta.", "p": 1, "h": 1}, {"hora": "13:00", "titulo": "Almuerzo", "detalle": "Proteína magra, medio plato de verdura, hidrato.", "p": 2, "h": 2}, {"hora": "16:30", "titulo": "Merienda", "detalle": "Yogur APIS Life y fruta.", "p": 1, "h": 2}, {"hora": "19:30", "titulo": "Cena", "detalle": "Proteína magra, verduras, hidrato.", "p": 2, "h": 2}]}, {"id": "fds", "nombre": "Fin de semana", "dias": [0, 6], "comidas": [{"hora": "09:00", "titulo": "Desayuno + creatina", "detalle": "Igual que en la semana; podés pasarlo a media mañana.", "p": 2, "h": 2}, {"hora": "14:00", "titulo": "Almuerzo", "detalle": "Asado o pastas con estrategia (ver Mi plan).", "p": 2, "h": 2}, {"hora": "17:00", "titulo": "Merienda", "detalle": "Opcional si el almuerzo fue tarde: FuXion + fruta.", "p": 1, "h": 1}, {"hora": "20:30", "titulo": "Cena", "detalle": "Proteína magra, verduras, hidrato.", "p": 2, "h": 2}]}]$j$::jsonb, $j${"fase": "Fase de déficit · octubre → diciembre 2026", "titulo": "Bajar a 105 kg", "titulo_destacado": "sin soltar músculo.", "bajada": "Este plan no es un menú fijo. Es un sistema: cada comida tiene una cantidad de bloques de proteína y de porciones de hidratos, y vos elegís con qué los completás. Si cumplís los bloques, cumpliste el plan.", "notas_metas": {"kcal": "~2200–2300 en descanso · ~2400 con entreno", "proteina": "7 bloques de 25 g + el resto del día", "hidratos": "8–9 porciones de ~25 g", "grasas": "incluye 30 g de aceite de oliva"}, "contador": {"metas": {"p": 7, "h": 9, "o": 2}, "etiquetas": {"p": "Bloques de proteína (25 g)", "h": "Porciones de hidratos (~25 g)", "o": "Cucharadas de aceite (15 g)"}, "botones": [{"grupo": "Proteína (1 bloque)", "clave": "p", "items": [{"n": "Pechuga 81 g"}, {"n": "Pescado 106 g"}, {"n": "Atún 1 lata"}, {"n": "Carne magra 85 g"}, {"n": "Revuelto 1+4"}, {"n": "FuXion 1¼ scoop"}, {"n": "Yogur APIS Life"}, {"n": "Ocasional"}]}, {"grupo": "Hidratos (1 porción)", "clave": "h", "items": [{"n": "2 tostadas"}, {"n": "Jugo"}, {"n": "Fruta"}, {"n": "Arroz / fideos"}, {"n": "Papa / batata"}, {"n": "Lentejas"}, {"n": "Choclo"}]}, {"grupo": "Grasas", "clave": "o", "items": [{"n": "1 cda. aceite", "q": 1}, {"n": "½ cda. aceite", "q": 0.5}]}]}, "nota_intercambios": "Cada línea aporta unos 25 g de proteína. Pesos en cocido. Las opciones “base” son para todos los días; las “ocasionales” traen más grasa, así que máximo una por día.", "intercambios_proteina": [{"n": "Pechuga de pollo", "cant": "81 g", "kcal": 133, "g": 3, "uso": "base"}, {"n": "Peceto, nalga o cuadrada", "cant": "85 g", "kcal": 135, "g": 4, "uso": "base"}, {"n": "Bola de lomo o lomo", "cant": "90 g", "kcal": 165, "g": 7, "uso": "base"}, {"n": "Carré de cerdo", "cant": "93 g", "kcal": 168, "g": 7, "uso": "base"}, {"n": "Pescado blanco (merluza, brótola, lenguado)", "cant": "106 g", "kcal": 123, "g": 2, "uso": "base"}, {"n": "Salmón rosado", "cant": "102 g", "kcal": 156, "g": 5, "uso": "base"}, {"n": "Atún al natural, escurrido", "cant": "129 g (≈1 lata)", "kcal": 111, "g": 1, "uso": "base"}, {"n": "Revuelto hiper-magro (1 huevo + 4 claras)", "cant": "1 porción", "kcal": 176, "g": 7, "uso": "base"}, {"n": "FuXion BioPro+ Sport", "cant": "31 g (≈1¼ scoop)", "kcal": 117, "g": 1, "uso": "base"}, {"n": "Yogur griego APIS Life (~¾ pote de 300 g)", "cant": "217 g", "kcal": 125, "g": 1, "uso": "base"}, {"n": "Pata-muslo sin piel", "cant": "103 g", "kcal": 180, "g": 8, "uso": "oca"}, {"n": "Vacío", "cant": "91 g", "kcal": 183, "g": 8, "uso": "oca"}, {"n": "Carne picada especial", "cant": "96 g", "kcal": 208, "g": 11, "uso": "oca"}, {"n": "Huevos enteros", "cant": "3 unidades (≈23 g prot.)", "kcal": 279, "g": 19, "uso": "oca"}, {"n": "Entraña", "cant": "96 g", "kcal": 211, "g": 12, "uso": "finde"}, {"n": "Asado de tira", "cant": "98 g", "kcal": 299, "g": 22, "uso": "finde"}], "porciones_hidratos": [{"n": "Pan integral Cero&Cero", "cant": "2 rebanadas (50 g)", "kcal": 114}, {"n": "Jugo de naranja exprimido", "cant": "1 vaso (250 ml)", "kcal": 113}, {"n": "Fruta de densidad media (manzana, pera, naranja, kiwi)", "cant": "180 g", "kcal": 97}, {"n": "Fruta de densidad alta (mango, banana, higo)", "cant": "132 g", "kcal": 98}, {"n": "Arroz integral", "cant": "115 g", "kcal": 117}, {"n": "Fideos", "cant": "81 g", "kcal": 128}, {"n": "Papa con piel, al horno", "cant": "118 g", "kcal": 110}, {"n": "Boniato (batata)", "cant": "124 g", "kcal": 107}, {"n": "Lentejas (+10 g prot.)", "cant": "111 g", "kcal": 141}, {"n": "Choclo", "cant": "119 g", "kcal": 114}], "textos": [{"t": "Grasas: con medida", "d": "Hasta 30 g de aceite de oliva extra virgen por día, unas 2 cucharadas soperas, medidas con cuchara. Además: ½ palta (50 g) o 1 cucharada de Finlandia Light (15 g) por día. Afuera: crema, manteca, salsas con crema y frituras."}, {"t": "Verduras: libres", "d": "Medio plato en almuerzo y cena. Hojas, tomate, zapallito, zucchini, brócoli, espárragos, zanahoria, zapallo. Papa, batata y choclo no son verdura: cuentan como hidratos."}, {"t": "Asado", "d": "Una porción de corte graso (asado de tira, vacío o entraña: unos 100 g cocidos) y el resto de la proteína en cortes magros. Ensalada grande, sin pan, sin achuras ni morcilla. Esa comida no lleva aceite extra."}, {"t": "Pastas", "d": "2 porciones de fideos (160 g cocidos) con salsa de tomate y 2 bloques de proteína magra adentro. Sin crema ni manteca. Ensalada al costado."}], "reglas": [{"t": "Proteína primero.", "d": "Cada comida principal arranca por los bloques. Si algo se queda afuera, que no sea la proteína."}, {"t": "Magro por defecto.", "d": "Pechuga en vez de pata-muslo: 3,6 g contra 7,8 g de grasa cada 100 g cocidos. Bola de lomo, peceto o nalga en vez de cortes grasos."}, {"t": "Aceite medido.", "d": "Hasta 30 g por día, con cuchara. Cero grasas ocultas en las preparaciones."}, {"t": "Medio plato verde.", "d": "En almuerzo y cena. Volumen y saciedad sin calorías."}, {"t": "Fruta con medida.", "d": "Hasta 3 frutas chicas por día, entre 300 y 350 g en total, y como máximo una de densidad alta. Suman unas 2 porciones de hidratos: contalas en el contador."}, {"t": "Tostada y jugo con creatina se quedan.", "d": "La tostada te sostiene la cabeza a la mañana; la creatina (5 g) va todos los días."}, {"t": "Un pesaje por semana.", "d": "En ayunas, mismo día y misma hora. La tendencia importa más que un número suelto."}], "pie": "Plan basado en la medición #12 (02/10/2026). Valores de la base C4E y, para los alimentos que no estaban, USDA FoodData Central (pesos en cocido) y rótulos de producto. Este plan no reemplaza una indicación médica."}$j$::jsonb, '2026-10-02', '2026-12-31');
  insert into public.mediciones (cliente_id, fecha, numero, peso_kg, talla_cm, pliegues_mm, perimetros_cm, masa_adiposa_kg, masa_muscular_kg, masa_residual_kg, masa_osea_kg, masa_piel_kg)
  values (v_id, '2026-01-30', 8, 106.0, 182.6, $j${"triceps": 14, "subescapular": 21, "supraespinal": 14, "abdominal": 20, "muslo_medio": 15, "pantorrilla": 10}$j$::jsonb, $j${"brazo_relajado": 34.8, "brazo_flexionado": 36.4, "antebrazo": 30.8, "torax": 112.5, "cintura": 101.9, "cadera": 111.5, "muslo_maximo": 68.0, "muslo_medio": 61.3, "pantorrilla": 43.2}$j$::jsonb, 25.1, 50.9, 14.4, 11.1, 4.6);
  insert into public.mediciones (cliente_id, fecha, numero, peso_kg, talla_cm, pliegues_mm, perimetros_cm, masa_adiposa_kg, masa_muscular_kg, masa_residual_kg, masa_osea_kg, masa_piel_kg)
  values (v_id, '2026-03-20', 9, 108.3, 182.6, $j${"triceps": 16, "subescapular": 22, "supraespinal": 14, "abdominal": 19, "muslo_medio": 12, "pantorrilla": 10}$j$::jsonb, $j${"brazo_relajado": 35.8, "brazo_flexionado": 36.0, "antebrazo": 31.1, "torax": 113.0, "cintura": 104.0, "cadera": 114.0, "muslo_maximo": 68.0, "muslo_medio": 61.5, "pantorrilla": 43.3}$j$::jsonb, 25.2, 52.3, 15.1, 11.1, 4.7);
  insert into public.mediciones (cliente_id, fecha, numero, peso_kg, talla_cm, pliegues_mm, perimetros_cm, masa_adiposa_kg, masa_muscular_kg, masa_residual_kg, masa_osea_kg, masa_piel_kg)
  values (v_id, '2026-05-08', 10, 106.5, 182.6, $j${"triceps": 15.5, "subescapular": 22, "supraespinal": 13.5, "abdominal": 19, "muslo_medio": 12, "pantorrilla": 10}$j$::jsonb, $j${"brazo_relajado": 35.2, "brazo_flexionado": 36.2, "antebrazo": 31.0, "torax": 115.0, "cintura": 105.5, "cadera": 114.6, "muslo_maximo": 69.0, "muslo_medio": 61.2, "pantorrilla": 42.6}$j$::jsonb, 24.3, 51.7, 15.0, 10.9, 4.5);
  insert into public.mediciones (cliente_id, fecha, numero, peso_kg, talla_cm, pliegues_mm, perimetros_cm, masa_adiposa_kg, masa_muscular_kg, masa_residual_kg, masa_osea_kg, masa_piel_kg)
  values (v_id, '2026-07-10', 11, 108.1, 182.6, $j${"triceps": 15.5, "subescapular": 22, "supraespinal": 14, "abdominal": 18, "muslo_medio": 15, "pantorrilla": 8}$j$::jsonb, $j${"brazo_relajado": 35.8, "brazo_flexionado": 36.1, "antebrazo": 31.5, "torax": 114.7, "cintura": 104.5, "cadera": 112.5, "muslo_maximo": 70.5, "muslo_medio": 61.5, "pantorrilla": 43.5}$j$::jsonb, 24.5, 53.2, 14.9, 10.9, 4.6);
  insert into public.mediciones (cliente_id, fecha, numero, peso_kg, talla_cm, pliegues_mm, perimetros_cm, masa_adiposa_kg, masa_muscular_kg, masa_residual_kg, masa_osea_kg, masa_piel_kg)
  values (v_id, '2026-10-02', 12, 107.9, 182.6, $j${"triceps": 15.5, "subescapular": 22.5, "supraespinal": 14, "abdominal": 18, "muslo_medio": 16, "pantorrilla": 9.5}$j$::jsonb, $j${"brazo_relajado": 35.9, "brazo_flexionado": 36.9, "antebrazo": 31.3, "torax": 113.7, "cintura": 104.6, "cadera": 114.5, "muslo_maximo": 69.5, "muslo_medio": 61.2, "pantorrilla": 43.4}$j$::jsonb, 25.2, 52.2, 15.0, 10.9, 4.6);
end
$do$;

-- Control: tiene que devolver 1 plan activo y 5 mediciones.
select c.nombre, c.email,
       (select count(*) from public.planes p where p.cliente_id = c.id and p.activo) as planes_activos,
       (select count(*) from public.mediciones m where m.cliente_id = c.id) as mediciones
from public.clientes c where c.nombre = 'Juanba (prueba)';
